from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential

def validate_structured_fields(document_url, api_endpoint, api_key):
    client = DocumentIntelligenceClient(api_endpoint, AzureKeyCredential(api_key))
    poller = client.begin_analyze_document("prebuilt-document", document_url=document_url)
    result = poller.result()

    required_fields = ["field1", "field2"]
    field_confidences = {}

    for field in result.documents[0].fields:
        if field.name in required_fields:
            field_confidences[field.name] = field.confidence

    for field in required_fields:
        if field not in field_confidences:
            return False, f"Missing required field: {field}"
        if field_confidences[field] < 0.5:
            return False, f"Low confidence for field: {field} with confidence {field_confidences[field]}"

    return True, "All required fields validated successfully"
